insert into public.answer_option_translations (option_id, lang, text) values
('fcfc9615-dabf-b5e2-f2b6-533100a62705', 'de', 'Seinen Siegelring vom Finger'),
('fcfc9615-dabf-b5e2-f2b6-533100a62705', 'en', 'His signet ring from his finger'),
('6eb519da-cff1-42a0-3280-70c9462e0aad', 'de', 'Das goldene Zepter, das er in der Hand hielt'),
('6eb519da-cff1-42a0-3280-70c9462e0aad', 'en', 'The golden scepter that he held in his hand'),
('0eb760fe-fa50-468d-e66e-fac0e25aa5e9', 'de', 'Sein königliches Gewand'),
('0eb760fe-fa50-468d-e66e-fac0e25aa5e9', 'en', 'His royal robe'),
('f6fe003c-ec5c-bc83-8026-c14bcbdc5435', 'de', 'Einen Kelch mit Wein'),
('f6fe003c-ec5c-bc83-8026-c14bcbdc5435', 'en', 'A cup of wine'),
('d715f7e2-1482-d2ba-0dd4-feb8b08ef473', 'de', 'Ihn hart zu bestrafen'),
('d715f7e2-1482-d2ba-0dd4-feb8b08ef473', 'en', 'To punish him severely'),
('91395b12-fc1f-4f3d-5b7a-dc97348c0906', 'de', 'Ihn zur Tempelarbeit zu geben'),
('91395b12-fc1f-4f3d-5b7a-dc97348c0906', 'en', 'To assign him to temple service'),
('8cb983d4-02f3-8ec8-7348-cd4d1a4459ed', 'de', 'Ihn nicht mehr als Sklaven, sondern als geliebten Bruder aufzunehmen'),
('8cb983d4-02f3-8ec8-7348-cd4d1a4459ed', 'en', 'To receive him no longer as a slave but as a beloved brother'),
('0ec88db0-965f-4225-c76c-33cbbd9e0fc1', 'de', 'Ihn zu verkaufen und den Erlös zu spenden'),
('0ec88db0-965f-4225-c76c-33cbbd9e0fc1', 'en', 'To sell him and donate the proceeds'),
('5e677869-4139-0d7c-06bf-4556e3690b2b', 'de', 'Die Städte zu verbrennen und Beute zu nehmen'),
('5e677869-4139-0d7c-06bf-4556e3690b2b', 'en', 'To burn the cities and take spoil'),
('4d02bcb2-a668-fd3e-c4b3-aa5d2a9327d2', 'de', 'Alles zu bannen, Mensch und Vieh'),
('4d02bcb2-a668-fd3e-c4b3-aa5d2a9327d2', 'en', 'To devote all to destruction, man and beast'),
('d569b0c5-1429-50a9-7137-d69978866984', 'de', 'Nur die Krieger zu töten'),
('d569b0c5-1429-50a9-7137-d69978866984', 'en', 'To kill only the warriors'),
('cf918157-2406-f00e-0d80-00370b135d31', 'de', 'Sie zinspflichtig zu machen'),
('cf918157-2406-f00e-0d80-00370b135d31', 'en', 'To make them pay tribute'),
('4fd5c7ac-b84d-eebd-ce7f-e55e81f2649d', 'de', 'Sieben Hörner'),
('4fd5c7ac-b84d-eebd-ce7f-e55e81f2649d', 'en', 'Seven horns'),
('546dc8ee-a4d5-2257-00f7-467cd981c133', 'de', 'Vier Hörner'),
('546dc8ee-a4d5-2257-00f7-467cd981c133', 'en', 'Four horns'),
('759ac460-4042-d600-d9a0-d44882f457c2', 'de', 'Zehn Hörner'),
('759ac460-4042-d600-d9a0-d44882f457c2', 'en', 'Ten horns'),
('483fc350-b349-228e-5640-55c12797a1cb', 'de', 'Zwölf Hörner'),
('483fc350-b349-228e-5640-55c12797a1cb', 'en', 'Twelve horns'),
('425d0601-08af-d282-f8d7-6de4b2e9d759', 'de', 'Ins Tal Josaphat'),
('425d0601-08af-d282-f8d7-6de4b2e9d759', 'en', 'To the Valley of Jehoshaphat'),
('819ef667-9041-87b0-8cad-b8d825735df7', 'de', 'An den Euphrat'),
('819ef667-9041-87b0-8cad-b8d825735df7', 'en', 'To the Euphrates'),
('b7ab4a0c-daf1-23bb-4aa8-3740cef35a3e', 'de', 'Nach Babylon'),
('b7ab4a0c-daf1-23bb-4aa8-3740cef35a3e', 'en', 'To Babylon'),
('df7a0530-6b3c-34dd-4c02-a9392133d622', 'de', 'Nach Harmagedon'),
('df7a0530-6b3c-34dd-4c02-a9392133d622', 'en', 'To Armageddon'),
('4e07f261-9795-eaeb-de27-42363e178e72', 'de', 'Gog, Magog, der Fürst der Finsternis, der Ankläger'),
('4e07f261-9795-eaeb-de27-42363e178e72', 'en', 'Gog, Magog, the prince of darkness, the accuser'),
('08c8d981-42be-7685-14e9-707dca04fb4b', 'de', 'Die alte Schlange, der Teufel, der Satan, der Verführer der ganzen Welt'),
('08c8d981-42be-7685-14e9-707dca04fb4b', 'en', 'The ancient serpent, the devil, Satan, the deceiver of the whole world'),
('eb4acbf1-342d-797e-a666-676f03e8491b', 'de', 'Abaddon, Apollyon, der Verderber, der Löwe'),
('eb4acbf1-342d-797e-a666-676f03e8491b', 'en', 'Abaddon, Apollyon, the Destroyer, the Lion'),
('0a531cad-a5af-122b-e849-ba81ead2a34d', 'de', 'Belial, Beelzebul, der Widersacher, der Betrüger'),
('0a531cad-a5af-122b-e849-ba81ead2a34d', 'en', 'Belial, Beelzebul, the adversary, the deceiver'),
('b409eb71-2f08-4aae-6b48-9ad7cdb93e6e', 'de', 'Durch Silvanus'),
('b409eb71-2f08-4aae-6b48-9ad7cdb93e6e', 'en', 'By Silvanus'),
('e9c908b3-1845-22ff-cb48-427a980953fd', 'de', 'Durch Tychikus'),
('e9c908b3-1845-22ff-cb48-427a980953fd', 'en', 'By Tychicus'),
('55411991-c548-5460-1ea2-d33bf5033128', 'de', 'Durch Lukas'),
('55411991-c548-5460-1ea2-d33bf5033128', 'en', 'By Luke'),
('21662c07-66e8-b58f-23f8-7dd82018ae59', 'de', 'Durch Markus'),
('21662c07-66e8-b58f-23f8-7dd82018ae59', 'en', 'By Mark'),
('e9ed6e0f-cc3e-0547-cb27-ebc9888c1662', 'de', 'Verhüllte Fallen, glimmende Kohlen, geborstene Krüge'),
('e9ed6e0f-cc3e-0547-cb27-ebc9888c1662', 'en', 'Hidden traps, smoldering coals, cracked jars'),
('77ccba90-24cf-2047-9b47-0ca778bcbfc7', 'de', 'Blinde Wächter, stumme Hunde, faule Hirten'),
('77ccba90-24cf-2047-9b47-0ca778bcbfc7', 'en', 'Blind watchmen, dumb dogs, lazy shepherds'),
('fcfadd86-27bd-b91e-3958-a6302a92401e', 'de', 'Zerbrochene Zisternen, welke Blumen, dürre Ranken'),
('fcfadd86-27bd-b91e-3958-a6302a92401e', 'en', 'Broken cisterns, withered flowers, dry vines'),
('f7a1d001-1e2d-58bc-d308-41b92dfbed7c', 'de', 'Wasserlose Wolken, Bäume ohne Frucht, wilde Meereswogen'),
('f7a1d001-1e2d-58bc-d308-41b92dfbed7c', 'en', 'Waterless clouds, fruitless trees, wild waves of the sea'),
('ed3806e8-b118-7518-13c1-b02bda745163', 'de', 'Weil sein Haus über ihm eingestürzt war'),
('ed3806e8-b118-7518-13c1-b02bda745163', 'en', 'Because his house had collapsed on top of him'),
('294898aa-1f59-4036-ee1b-c4b4a70d8a4b', 'de', 'Weil ihn die Richter zum Tode verurteilt hatten'),
('294898aa-1f59-4036-ee1b-c4b4a70d8a4b', 'en', 'Because the judges had condemned him to death'),
('35375bab-797b-4fe1-47d5-2bc6c2d89b6b', 'de', 'Weil die Türen offen standen und er meinte, die Gefangenen seien entflohen'),
('35375bab-797b-4fe1-47d5-2bc6c2d89b6b', 'en', 'Because the doors stood open and he thought the prisoners had escaped'),
('2a4770cb-bfe3-a7e2-746c-7d5d9ec11dba', 'de', 'Weil er die Botschaft des Paulus nicht ertragen konnte'),
('2a4770cb-bfe3-a7e2-746c-7d5d9ec11dba', 'en', 'Because he could not bear Paul''s message'),
('4f483136-70b8-4ba6-80f5-4379be9c34ae', 'de', 'Sie hatten allein Boten bis nach Jerusalem gesandt'),
('4f483136-70b8-4ba6-80f5-4379be9c34ae', 'en', 'They alone sent messengers as far as Jerusalem'),
('a87b5566-be55-1d90-9e98-5cdbea4c9f2a', 'de', 'Sie hatten allein für ihn im Gefängnis gebürgt'),
('a87b5566-be55-1d90-9e98-5cdbea4c9f2a', 'en', 'They alone stood surety for him in prison'),
('ce45b9a4-b0e0-643a-1245-cb5107bfd43a', 'de', 'Sie hatten allein mit ihm im Anfang geteilt in Sachen des Gebens und Nehmens'),
('ce45b9a4-b0e0-643a-1245-cb5107bfd43a', 'en', 'They alone shared with him at the first in the matter of giving and receiving'),
('55bf185b-e883-5b74-9703-fff25889ae76', 'de', 'Sie hatten allein ihm ein Haus in Rom gekauft'),
('55bf185b-e883-5b74-9703-fff25889ae76', 'en', 'They alone bought him a house in Rome'),
('d619dfbb-ed25-c4a0-2341-fa5cbaa90904', 'de', 'Er zog seinen Schuh aus und gab ihn Boas'),
('d619dfbb-ed25-c4a0-2341-fa5cbaa90904', 'en', 'He drew off his sandal and gave it to Boaz'),
('c0d4e677-7321-8c28-6e86-fb4ddf7a5a8c', 'de', 'Er legte seine Hand unter Boas'' Hüfte'),
('c0d4e677-7321-8c28-6e86-fb4ddf7a5a8c', 'en', 'He put his hand under Boaz''s thigh'),
('c80e686a-5f48-3cd3-eeab-6bebbddb29c6', 'de', 'Er zerriss seinen Mantel vor den Ältesten'),
('c80e686a-5f48-3cd3-eeab-6bebbddb29c6', 'en', 'He tore his cloak before the elders'),
('7702cc5a-46d3-c6f0-0f5a-021b15a1640e', 'de', 'Er warf einen Stein auf den Steinhaufen'),
('7702cc5a-46d3-c6f0-0f5a-021b15a1640e', 'en', 'He cast a stone upon the heap'),
('abe13b21-1875-3a84-6847-1708112b2093', 'de', 'Sie warf sie in den Fluss'),
('abe13b21-1875-3a84-6847-1708112b2093', 'en', 'She threw them in the river'),
('a4b0bf55-cbc1-cf47-1e86-45333ad8886e', 'de', 'Sie gab sie einer Magd'),
('a4b0bf55-cbc1-cf47-1e86-45333ad8886e', 'en', 'She gave them to a maid'),
('19f9c29f-1918-1a0a-b155-56c53b1698c7', 'de', 'Sie setzte sich auf sie im Kamelsattel'),
('19f9c29f-1918-1a0a-b155-56c53b1698c7', 'en', 'She sat on them in the camel''s saddle'),
('2af49c1e-b617-6a58-9708-23cacbd2df96', 'de', 'Sie vergrub sie unter einem Baum'),
('2af49c1e-b617-6a58-9708-23cacbd2df96', 'en', 'She buried them under a tree'),
('7ee67e3b-ee25-57a1-23ec-c839dce6bdd2', 'de', 'In den Tiefen des salzigen Meeres'),
('7ee67e3b-ee25-57a1-23ec-c839dce6bdd2', 'en', 'In the depths of the salt sea'),
('dc47d94a-5157-9cd0-5981-0321bc895e1d', 'de', 'In den Höhlen der hohen Berge'),
('dc47d94a-5157-9cd0-5981-0321bc895e1d', 'en', 'In the caves of the high mountains'),
('8c6aa07a-86be-4c19-14b3-4aa6c4224b33', 'de', 'Am Ufer des Flusses im hellen Sonnenschein'),
('8c6aa07a-86be-4c19-14b3-4aa6c4224b33', 'en', 'On the riverbank in bright sunshine'),
('8f4b820e-1c0f-d7d9-07fb-7e96cafab991', 'de', 'Unter Lotosbüschen, im Versteck von Rohr und Sumpf'),
('8f4b820e-1c0f-d7d9-07fb-7e96cafab991', 'en', 'Under the lotus plants, hidden by reeds and marsh'),
('a915f589-b2fb-a669-dbe9-bcf39d7332b2', 'de', 'Ihr sollt es mir doppelt vergelten'),
('a915f589-b2fb-a669-dbe9-bcf39d7332b2', 'en', 'You shall repay me double'),
('211b6186-0d23-46c7-46b2-4be9c229afee', 'de', 'Ihr gedachtet es böse, aber Gott gedachte es gut zu machen'),
('211b6186-0d23-46c7-46b2-4be9c229afee', 'en', 'You meant it for evil, but God meant it for good'),
('20a870f5-c893-346f-89fc-84dd08570be6', 'de', 'Der HERR wird euch strafen'),
('20a870f5-c893-346f-89fc-84dd08570be6', 'en', 'The LORD will punish you'),
('4a1c504c-9af2-5dbf-a7d5-0b0004382568', 'de', 'Ich habe es längst vergessen'),
('4a1c504c-9af2-5dbf-a7d5-0b0004382568', 'en', 'I have long forgotten it'),
('109c9847-d146-1917-d60a-687764828c45', 'de', 'Sie flohen nach Ägypten'),
('109c9847-d146-1917-d60a-687764828c45', 'en', 'They fled to Egypt'),
('b4008118-e378-ca58-526a-966c63bbd550', 'de', 'Sie krönten Adonija sogleich'),
('b4008118-e378-ca58-526a-966c63bbd550', 'en', 'They crowned Adonijah at once'),
('ede881a9-93c4-7f0c-9a76-1a1ba8819048', 'de', 'Sie erschraken, standen auf und zerstreuten sich'),
('ede881a9-93c4-7f0c-9a76-1a1ba8819048', 'en', 'They were afraid, rose up, and scattered'),
('eac5ed15-1150-e376-5798-0795e88a3078', 'de', 'Sie zogen mit dem Schwert gegen Salomo'),
('eac5ed15-1150-e376-5798-0795e88a3078', 'en', 'They marched with the sword against Solomon'),
('7643cdd8-b72f-7157-77cd-a7da1865275d', 'de', 'Sie sollten seine Gebeine aus Ägypten hinaufbringen'),
('7643cdd8-b72f-7157-77cd-a7da1865275d', 'en', 'They should carry his bones up out of Egypt'),
('6b2e46a0-0627-6fc6-b321-4c6112a7c411', 'de', 'Sie sollten ihn in Hebron bestatten'),
('6b2e46a0-0627-6fc6-b321-4c6112a7c411', 'en', 'They should bury him in Hebron'),
('7f7d2efc-29f7-16a2-6cfb-46a2a0e0867e', 'de', 'Sie sollten seine Gebeine verbrennen'),
('7f7d2efc-29f7-16a2-6cfb-46a2a0e0867e', 'en', 'They should burn his bones'),
('0ddf5d96-f331-b781-7a7b-736e176e0df9', 'de', 'Sie sollten ihn bei Rahel begraben'),
('0ddf5d96-f331-b781-7a7b-736e176e0df9', 'en', 'They should bury him beside Rachel'),
('35db1ce4-6fb2-0b51-176e-560d873b24ba', 'de', 'Weil es Blut in sich traegt'),
('35db1ce4-6fb2-0b51-176e-560d873b24ba', 'en', 'Because it carries blood within it'),
('c10a56ba-6dd1-8546-a5f5-dc3772f0510b', 'de', 'Weil es in der Wueste lebt'),
('c10a56ba-6dd1-8546-a5f5-dc3772f0510b', 'en', 'Because it lives in the desert'),
('174233d7-4d3a-da38-effb-876c96232d35', 'de', 'Weil es die Klaue nicht ganz spaltet'),
('174233d7-4d3a-da38-effb-876c96232d35', 'en', 'Because it does not fully split the hoof'),
('05da44d6-c7c8-030b-71bd-0ee35683f02d', 'de', 'Weil es zu den Raubtieren zaehlt'),
('05da44d6-c7c8-030b-71bd-0ee35683f02d', 'en', 'Because it is counted among predators'),
('942ee10d-41f5-aa8b-8826-9cd78ef44fd1', 'de', 'Sie verlangten ein weiteres Zeichen vom Himmel'),
('942ee10d-41f5-aa8b-8826-9cd78ef44fd1', 'en', 'They demanded another sign from heaven'),
('3b2fa836-e337-2b10-7cd9-3026e741e0b7', 'de', 'Sie brachten ihre Kranken auf die Gassen hinaus'),
('3b2fa836-e337-2b10-7cd9-3026e741e0b7', 'en', 'They brought their sick out into the streets'),
('63272c13-0c33-c618-236e-7d6618fe2714', 'de', 'Sie steinigten Petrus vor den Toren der Stadt'),
('63272c13-0c33-c618-236e-7d6618fe2714', 'en', 'They stoned Peter outside the city gates'),
('666dc7cd-ad5e-a395-21d3-ca2857bdcfc1', 'de', 'Alle, die dort wohnten, sahen ihn und bekehrten sich zum Herrn'),
('666dc7cd-ad5e-a395-21d3-ca2857bdcfc1', 'en', 'All who lived there saw him and turned to the Lord'),
('d75fc278-c8ef-42da-4024-feda9123f67c', 'de', 'Jesus kenne ich und von Paulus weiß ich, wer aber seid ihr'),
('d75fc278-c8ef-42da-4024-feda9123f67c', 'en', 'Jesus I know and Paul I know, but who are you'),
('36a996c0-09af-2b43-8dad-4f038d4238d6', 'de', 'Weichet von mir, ihr Verfluchten'),
('36a996c0-09af-2b43-8dad-4f038d4238d6', 'en', 'Depart from me, you cursed ones'),
('062f0b0f-ae6f-361f-d88c-d4c44ec47d1f', 'de', 'Ihr seid stärker als ich'),
('062f0b0f-ae6f-361f-d88c-d4c44ec47d1f', 'en', 'You are stronger than I'),
('41c668e7-eb8b-3553-0bbf-8080adbee5b1', 'de', 'Ich fahre aus in Frieden'),
('41c668e7-eb8b-3553-0bbf-8080adbee5b1', 'en', 'I come out in peace'),
('6155255c-6e9e-8b40-7ee7-7a5fd629a3cc', 'de', 'Sein Atem entzündet Kohlen, und Flammen fahren aus seinem Rachen'),
