('54d35370-b880-33f6-fd90-a872274c9c8d', 'en', 'Stephanas'),
('4cde5fa3-2c32-e9a4-a29b-983eb79614eb', 'de', 'Gaius'),
('4cde5fa3-2c32-e9a4-a29b-983eb79614eb', 'en', 'Gaius'),
('fd4f09d7-abc5-f97b-015f-e5ebb41ed08a', 'de', 'Er nahm Gold aus dem königlichen Schatz'),
('fd4f09d7-abc5-f97b-015f-e5ebb41ed08a', 'en', 'He took gold from the royal treasury'),
('7df4fa56-3135-bd36-4790-edfbbd677446', 'de', 'Er zog eine Kopfsteuer im ganzen Land ein'),
('7df4fa56-3135-bd36-4790-edfbbd677446', 'en', 'He levied a poll tax throughout the land'),
('e0dc8ebf-4721-c172-a7f5-2c826774c942', 'de', 'Er bohrte ein Loch in den Deckel einer Lade'),
('e0dc8ebf-4721-c172-a7f5-2c826774c942', 'en', 'He bored a hole in the lid of a chest'),
('5c8c8544-ed51-e26a-0c00-64167465f84a', 'de', 'Er verkaufte heilige Geräte'),
('5c8c8544-ed51-e26a-0c00-64167465f84a', 'en', 'He sold sacred vessels'),
('30f20237-8fb9-f0a0-0276-886d3eb9e33e', 'de', 'Wer teilt dem Regen seine Bahnen zu?'),
('30f20237-8fb9-f0a0-0276-886d3eb9e33e', 'en', 'Who assigns the rain its paths?'),
('04156ab9-66c2-7bdf-8024-faeb24a9f527', 'de', 'Wer lässt es regnen auf das Land ohne Menschen?'),
('04156ab9-66c2-7bdf-8024-faeb24a9f527', 'en', 'Who sends rain on a land where no one lives?'),
('bd2f01e0-a3b5-e0d6-f598-09c039af08a2', 'de', 'Wer sammelt den Regen in den Wolken?'),
('bd2f01e0-a3b5-e0d6-f598-09c039af08a2', 'en', 'Who gathers the rain in the clouds?'),
('e60f13ec-15e4-5729-1929-f342f03c61ff', 'de', 'Wer misst die Tropfen des Regens ab?'),
('e60f13ec-15e4-5729-1929-f342f03c61ff', 'en', 'Who measures out the drops of rain?'),
