('73522c6c-88db-9f2f-aee3-779f179c60a2', 'en', 'He should bring it to the priest'),
('a9b04d1f-14f1-4967-fe9c-7eb6a073b0d2', 'de', 'Fünf'),
('a9b04d1f-14f1-4967-fe9c-7eb6a073b0d2', 'en', 'Five'),
('edc41292-33a4-1242-d1aa-eeca1cc3d193', 'de', 'Zwölf'),
('edc41292-33a4-1242-d1aa-eeca1cc3d193', 'en', 'Twelve'),
('ff097d5a-c489-b4e5-79c5-c7a0d4eef91b', 'de', 'Drei'),
('ff097d5a-c489-b4e5-79c5-c7a0d4eef91b', 'en', 'Three'),
('e3721f8a-e307-d926-9a76-625313e2e39b', 'de', 'Sieben'),
('e3721f8a-e307-d926-9a76-625313e2e39b', 'en', 'Seven'),
('72ccdebc-9f72-3d07-ddec-3ed63c51c08e', 'de', 'Ob man ungesäuertes Brot essen müsse'),
('72ccdebc-9f72-3d07-ddec-3ed63c51c08e', 'en', 'Whether one must eat unleavened bread'),
('62e41759-e76a-2567-2311-33c33739b39e', 'de', 'Ob geheiligtes Fleisch im Gewand anderes heilige'),
('62e41759-e76a-2567-2311-33c33739b39e', 'en', 'Whether consecrated meat in a garment sanctifies other things'),
('2ea40235-17d2-559b-9235-e277806b958f', 'de', 'Ob man am Sabbat opfern dürfe'),
('2ea40235-17d2-559b-9235-e277806b958f', 'en', 'Whether one may sacrifice on the Sabbath'),
('ee9c32a3-c6f1-5e0a-6f19-b45e27512092', 'de', 'Ob Fremde den Tempel betreten dürften'),
('ee9c32a3-c6f1-5e0a-6f19-b45e27512092', 'en', 'Whether foreigners may enter the temple'),
('435900c6-8385-add8-ff58-15bf1836f031', 'de', 'Ein Prophet mit einem Buch in der Hand'),
('435900c6-8385-add8-ff58-15bf1836f031', 'en', 'A prophet with a book in his hand'),
('43829482-b301-2b0b-3920-88591ec0819a', 'de', 'Der Erzengel Michael in Rüstung'),
('43829482-b301-2b0b-3920-88591ec0819a', 'en', 'The archangel Michael in armor'),
('93f7e28b-dc56-714e-b43d-a679b1420b52', 'de', 'Der König der Meder auf dem Thron'),
('93f7e28b-dc56-714e-b43d-a679b1420b52', 'en', 'The king of the Medes on the throne'),
('de9c90c5-d777-a350-d173-f096e0ffefb8', 'de', 'Gott, dessen Kleid weiß wie Schnee und Haar wie reine Wolle war'),
('de9c90c5-d777-a350-d173-f096e0ffefb8', 'en', 'God, whose garment was white as snow and hair like pure wool'),
('50d47700-74e2-7805-5009-60f4c9ef358a', 'de', 'Einen weißen Stein mit neuem Namen'),
('50d47700-74e2-7805-5009-60f4c9ef358a', 'en', 'A white stone with a new name'),
