('c2d2c638-9486-8033-7b49-cde4f57b7cd0', 'en', 'Five men'),
('99a78bc9-39cf-35f1-2132-3a8ec040d003', 'de', 'Zehn Männer'),
('99a78bc9-39cf-35f1-2132-3a8ec040d003', 'en', 'Ten men'),
