('531aab7d-4c94-0764-86a9-0d4edbd582ca', 'en', 'They sent a messenger to report it'),
('87183ecc-f69d-1a0a-e270-02c647692bfa', 'de', 'Er trank es dankbar'),
('87183ecc-f69d-1a0a-e270-02c647692bfa', 'en', 'He drank it gratefully'),
