('2864809e-a973-f921-f64f-f377460f27f6', 'en', 'Gold, bronze, silver, clay, and iron'),
('f331f6bd-10af-f446-8ef5-96d5a16b6032', 'de', 'Eisen, Erz, Silber, Gold und Holz'),
('f331f6bd-10af-f446-8ef5-96d5a16b6032', 'en', 'Iron, bronze, silver, gold, and wood'),
