('34467b33-df9e-3d63-41f4-3243f420ad5e', 'en', 'A year of fasting and prayer'),
('837c782f-2910-4005-958e-c613c2e89ff5', 'de', 'Um seinen Segen für das ganze Volk'),
('837c782f-2910-4005-958e-c613c2e89ff5', 'en', 'For his blessing on the whole people'),
('fecad5e5-db9e-1b49-9f16-25135e112e89', 'de', 'Um seinen Mantel und seinen Stab'),
('fecad5e5-db9e-1b49-9f16-25135e112e89', 'en', 'For his cloak and his staff'),
