('5a3e7c12-c910-8c00-36d9-b05bca83332f', 'en', 'For the office of high priest'),
('7c67686f-a114-5558-6027-b9a21d2c5dc5', 'de', 'Sie hat viel gearbeitet unter den Heiligen'),
('7c67686f-a114-5558-6027-b9a21d2c5dc5', 'en', 'She has labored much among the saints'),
