('d813a644-dee1-3d23-c787-ce1c27f8c251', 'en', 'Josheb-Basshebeth the Tahkemonite'),
('18dfc445-e29b-da97-b5aa-5d6575ca673d', 'de', 'Abischai, der Bruder Joabs'),
('18dfc445-e29b-da97-b5aa-5d6575ca673d', 'en', 'Abishai the brother of Joab'),
