('1f0e455c-16db-4c5d-fba5-7132463cae1f', 'en', 'Simeon'),
('a6512e7b-13c9-5444-0630-7a75229f1250', 'de', 'Ruben'),
('a6512e7b-13c9-5444-0630-7a75229f1250', 'en', 'Reuben'),
('8d601d2d-ca15-8840-bb67-3ef146890619', 'de', 'Ein Mondlauf bis zum Opfer'),
('8d601d2d-ca15-8840-bb67-3ef146890619', 'en', 'One lunar cycle until the offering'),
