('24a05367-a86b-2a2a-19dd-1b781acf12e7', 'en', 'A widow of eighty-four who fasted and prayed night and day'),
('cb4787d2-c148-3082-e7be-8039b05a237f', 'de', 'Eine reiche Kaufmannsfrau aus Jerusalem'),
('cb4787d2-c148-3082-e7be-8039b05a237f', 'en', 'A wealthy merchant''s wife of Jerusalem'),
('d191992a-49c2-c909-7454-cf532c0d599f', 'de', 'Sechzig Monate'),
('d191992a-49c2-c909-7454-cf532c0d599f', 'en', 'Sixty months'),
('ce2ebb6a-82d1-7a6b-f4c2-6bcc58d6f207', 'de', 'Dreißig Monate'),
('ce2ebb6a-82d1-7a6b-f4c2-6bcc58d6f207', 'en', 'Thirty months'),
('02e6edf9-8518-fd20-8405-173a1867f7f3', 'de', 'Fünf Monate'),
