insert into public.answer_option_translations (option_id, lang, text) values
('1aca130b-0837-ad34-c87f-cff89737c11c', 'de', 'In der Zisterne von Aseka'),
('1aca130b-0837-ad34-c87f-cff89737c11c', 'en', 'In the cistern of Azekah'),
('c5b325d4-065d-f802-1dc0-040cc7d5c942', 'de', 'In den Bergen von Juda'),
('c5b325d4-065d-f802-1dc0-040cc7d5c942', 'en', 'In the mountains of Judah'),
('833df363-da53-c2f5-67da-7298a5fb21a5', 'de', 'In der Höhle bei Makkeda'),
('833df363-da53-c2f5-67da-7298a5fb21a5', 'en', 'In the cave at Makkedah'),
('bd4c26d5-88a8-6d25-f31b-7a0dc6e51f59', 'de', 'In den Wäldern von Bet-Horon'),
('bd4c26d5-88a8-6d25-f31b-7a0dc6e51f59', 'en', 'In the forests of Beth-Horon'),
('d1071074-abb9-7477-a622-f5d0b6c54d1b', 'de', 'Er betete, und Feuer fiel auf die Opfergabe'),
('d1071074-abb9-7477-a622-f5d0b6c54d1b', 'en', 'He prayed, and fire fell on the offering'),
('a249155f-77be-0312-29ad-8c9a8f3b4ac3', 'de', 'Er betete, und die Toten wurden auferweckt'),
('a249155f-77be-0312-29ad-8c9a8f3b4ac3', 'en', 'He prayed, and the dead were raised'),
('43a5db03-d0eb-e5af-b537-95f6df374a86', 'de', 'Er betete, und das Meer teilte sich'),
('43a5db03-d0eb-e5af-b537-95f6df374a86', 'en', 'He prayed, and the sea parted'),
('2caef0c2-fec2-439e-8e35-9010b5137c09', 'de', 'Er betete, und es regnete drei Jahre und sechs Monate nicht'),
('2caef0c2-fec2-439e-8e35-9010b5137c09', 'en', 'He prayed, and it did not rain for three years and six months'),
('e5def55f-863f-7e5b-3fb4-b79a7a160cb8', 'de', 'Ein Wolf, ein Panther, ein Stier und ein Ungeheuer'),
('e5def55f-863f-7e5b-3fb4-b79a7a160cb8', 'en', 'A wolf, a panther, a bull, and a monster'),
('49881a80-eef1-7864-b834-faae55ee10b6', 'de', 'Ein Ochse, ein Löwe, ein Mensch und ein Adler'),
('49881a80-eef1-7864-b834-faae55ee10b6', 'en', 'An ox, a lion, a man, and an eagle'),
('2c81217c-3889-d85f-1581-00a6fbbeb71b', 'de', 'Ein Löwe, ein Bär, ein Leopard und ein schreckliches Tier'),
('2c81217c-3889-d85f-1581-00a6fbbeb71b', 'en', 'A lion, a bear, a leopard, and a terrifying beast'),
('62677472-4886-d670-d3a1-28a4c2928d7e', 'de', 'Ein Widder, ein Ziegenbock, ein Adler und ein Drache'),
('62677472-4886-d670-d3a1-28a4c2928d7e', 'en', 'A ram, a goat, an eagle, and a dragon'),
('53bfbe44-f457-2acb-934a-af6751ebc52f', 'de', 'In ihren Hufen aus Erz und ihren Flügeln'),
('53bfbe44-f457-2acb-934a-af6751ebc52f', 'en', 'In their hooves of bronze and their wings'),
('27959f17-be67-ab56-1df0-8765e38a572b', 'de', 'In ihren Augen aus Feuer und ihren Zähnen'),
('27959f17-be67-ab56-1df0-8765e38a572b', 'en', 'In their eyes of fire and their teeth'),
('9cfa803a-1837-6e3d-15ea-647cee0fe2a0', 'de', 'In ihren Mäulern und in ihren Schwänzen, die Schlangen mit Köpfen gleichen'),
('9cfa803a-1837-6e3d-15ea-647cee0fe2a0', 'en', 'In their mouths and in their tails, which are like serpents with heads'),
('fba68b61-fc71-2af2-eaf3-5d1eadb65f19', 'de', 'In ihren Hörnern und ihren Klauen'),
('fba68b61-fc71-2af2-eaf3-5d1eadb65f19', 'en', 'In their horns and their claws'),
('404eb0b0-29ee-9eb5-947d-eea14b6644f4', 'de', 'Warum verbirgst du dein Angesicht vor mir'),
('404eb0b0-29ee-9eb5-947d-eea14b6644f4', 'en', 'Why do you hide your face from me'),
('f29bb0bb-2d3c-d56d-23df-00748e73148a', 'de', 'Mein Sohn Absalom, wäre ich doch an deiner Statt gestorben'),
('f29bb0bb-2d3c-d56d-23df-00748e73148a', 'en', 'My son Absalom, would I had died instead of you'),
('45637a05-43b1-a466-319d-e566e4196234', 'de', 'Der HERR hat gegeben, der HERR hat genommen'),
('45637a05-43b1-a466-319d-e566e4196234', 'en', 'The LORD gave, the LORD has taken away'),
('575909d7-5a2a-d34f-721b-c161740f1be5', 'de', 'Er ist dahin, ich aber werde zu ihm gehen'),
('575909d7-5a2a-d34f-721b-c161740f1be5', 'en', 'He is gone, but I shall go to him'),
('3d97c7bc-54ab-e8c4-6d21-f0620340a273', 'de', 'Einen Bogen Jonatans'),
('3d97c7bc-54ab-e8c4-6d21-f0620340a273', 'en', 'A bow of Jonathan'),
('d805c929-12b3-a236-fcd0-5009a655da6a', 'de', 'Das Schwert Goliats'),
('d805c929-12b3-a236-fcd0-5009a655da6a', 'en', 'The sword of Goliath'),
('76212fec-ddc7-66b0-e2a5-7c8d568e4666', 'de', 'Ein Wurfholz der Priester'),
('76212fec-ddc7-66b0-e2a5-7c8d568e4666', 'en', 'A throwing stick of the priests'),
