('44b4b82c-7746-0478-6a57-f8679a77f2e6', 'en', 'To Galatia'),
('59fdaedd-ee35-fda9-7cf2-11bdc509747b', 'de', 'Nach Kreta'),
('59fdaedd-ee35-fda9-7cf2-11bdc509747b', 'en', 'To Crete'),
('3d4bb80d-761a-d49a-4ae5-a51917080a6f', 'de', 'Nach Dalmatien'),
('3d4bb80d-761a-d49a-4ae5-a51917080a6f', 'en', 'To Dalmatia'),
